using System.Diagnostics;using System.Text.Json;using Dip.Application.Features.Intelligence;using Dip.Application.Features.QualityAutomation;
namespace Dip.Infrastructure.Intelligence;
public sealed class ReliabilityRunner:IReliabilityRunner
{
 readonly IQaWorkspaceResolver _workspace;public ReliabilityRunner(IQaWorkspaceResolver w){_workspace=w;}
 public async Task<ReliabilityResult> RunAsync(ReliabilityRequest r,string artifactRoot,CancellationToken ct){var ws=_workspace.Resolve(r.WorkspaceRelativePath);if(Path.IsPathRooted(r.Executable))throw new InvalidOperationException("Executable must be workspace-relative.");var exe=Path.GetFullPath(Path.Combine(ws,r.Executable));var repeat=r.SoakMinutes>0?1:Math.Clamp(r.RepeatCount,3,200);int pass=0,fail=0,to=0;var durations=new List<double>();long startMem=GC.GetTotalMemory(true),peak=startMem;for(int i=0;i<repeat;i++){var psi=new ProcessStartInfo(exe){WorkingDirectory=ws,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in r.Arguments)psi.ArgumentList.Add(a);using var p=Process.Start(psi)??throw new InvalidOperationException("Target unavailable");var sw=Stopwatch.StartNew();using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(r.SoakMinutes>0?TimeSpan.FromMinutes(Math.Clamp(r.SoakMinutes,1,720)):TimeSpan.FromMinutes(10));try{await p.WaitForExitAsync(timeout.Token);if(p.ExitCode==0)pass++;else fail++;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){to++;try{p.Kill(true);}catch{}}sw.Stop();durations.Add(sw.Elapsed.TotalMilliseconds);peak=Math.Max(peak,GC.GetTotalMemory(false));}var first=durations.Count>0?durations.First():0;var last=durations.Count>0?durations.Last():0;var drift=first<=0?0:(decimal)Math.Max(0,(last-first)/first*100);var rate=decimal.Round(100m*(fail+to)/Math.Max(1,repeat),2);var flaky=rate is >0 and <100?Math.Min(100,rate*1.5m):0;var growth=decimal.Round((peak-startMem)/1024m/1024m,2);var payload=JsonSerializer.Serialize(new{runs=repeat,pass,fail,timeouts=to,failureRate=rate,flakyScore=flaky,memoryGrowthMb=growth,performanceDriftPercent=drift,durationsMs=durations});await File.WriteAllTextAsync(Path.Combine(artifactRoot,"reliability.json"),payload,ct);return new(repeat,pass,fail,to,rate,flaky,growth,decimal.Round(drift,2),payload);}
}
